//! Independently expected whole-account worn conversion matrices, not developer fixtures.
use gielinor_world::{equipment::{WearType,Event},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,worn_item_swap::Rule,variables::{Varp,Varbit,Transmit},bank_actions::Binding,wearpos,CoordGrid};
fn fixture(reverse:bool,member:bool,occupied:bool,holes:usize)->(World,ActorId,i32,i32,usize,usize){let(input,output,from,to)=if reverse{(29775,25644,5,3)}else{(25644,29775,3,5)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b,f,t)in[(25644,29775,3,5),(29775,25644,5,3)]{w.worn_item_swaps.insert(a,Rule{output:b,from_slot:f,to_slot:t,button_operation:2});w.wear_types.types.insert(a,WearType{primary:Some(f),secondary:[None,None],requirements:vec![]});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);let mut d=PlayerData::new(1,"Independent worn hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==4{input}else{1931},count:1,vars:0})).unwrap();}for s in(0..28).filter(|s|*s!=4).take(holes){d.inventory.restore_slot(s,None).unwrap();}d.equipment.restore_slot(from,Some(Item{id:input,count:1,vars:0})).unwrap();d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();if occupied{d.equipment.restore_slot(to,Some(Item{id:999,count:1,vars:9})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();(w,a,input,output,from,to)}
fn listeners(w:&mut World){let varp=|id|Varp{id,permanent:true,transmit:Transmit::Always,bit_protect:false,client_code:-1};let bit=|id|Binding{base:varp(id),bit:Varbit{base:id,lsb:0,msb:7}};w.wearpos=Some(wearpos::Config{special:varp(301),stance:varp(43),category:bit(843),level:bit(8),decimal:bit(9),combat_stats:[0,1,2,3,4,6,5],items:[(25644,wearpos::Item{category:17,..Default::default()}),(29775,wearpos::Item::default()),(999,wearpos::Item{category:7,..Default::default()})].into()});}
#[test]fn eight_real_listener_orders_observe_removal_before_equipping(){let mut n=0;for reverse in[false,true]{for member in[false,true]{for occupied in[false,true]{let(mut w,a,input,output,from,to)=fixture(reverse,member,occupied,1);listeners(&mut w);let before=w.data(a).unwrap().clone();w.submit(a,Action::SwapWornItem{slot:from,item:input}).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().stats,before.stats);let events=w.drain_events();let order:Vec<_>=events.iter().filter_map(|e|match e{WorldEvent::WearposEffects{result:Ok(_),..}=>Some(0),WorldEvent::EquipmentResult{unequipping:true,result:Ok(_),..}=>Some(1),WorldEvent::EquipmentResult{unequipping:false,result:Ok(_),..}=>Some(2),_=>None}).collect();assert_eq!(order,if member && !occupied{vec![0,1,0,2]}else{vec![0,1]});let categories:Vec<_>=events.iter().filter_map(|e|if let WorldEvent::WearposEffects{result:Ok(v),..}=e{Some(v)}else{None}).flat_map(|v|v.iter()).filter_map(|e|if let wearpos::Event::Variable(v)=e{(v.id==843).then_some(v.value)}else{None}).collect();let initial_category=if reverse && occupied{7}else{0};assert_eq!(categories,if member && !occupied{vec![0,if reverse{17}else{0}]}else{vec![initial_category]});assert_eq!(w.data(a).unwrap().equipment.get(from),None);if member && !occupied{assert_eq!(w.data(a).unwrap().equipment.get(to).unwrap().id,output);}n+=1;}}}assert_eq!(n,8);println!("PG_WORN real listener cases={n}");}
#[test]fn eight_member_base_requirement_and_nonmember_no_equip_controls(){let mut n=0;for reverse in[false,true]{for member in[false,true]{for meets in[false,true]{let(mut w,a,input,output,from,to)=fixture(reverse,member,false,1);w.wear_types.types.get_mut(&output).unwrap().requirements=vec![(0,10)];w.data_mut(a).unwrap().stats.set_base(0,if meets{10}else{1});w.data_mut(a).unwrap().stats.set_current(0,99);let before=w.data(a).unwrap().clone();w.submit(a,Action::SwapWornItem{slot:from,item:input}).unwrap();w.tick().unwrap();let d=w.data(a).unwrap();assert_eq!(d.stats,before.stats);if member && !meets{assert_eq!(d.inventory,before.inventory);assert_eq!(d.equipment,before.equipment);}else{assert!(d.equipment.get(from).is_none());if member{assert_eq!(d.equipment.get(to).unwrap().id,output);assert_eq!(d.inventory,before.inventory);}else{let mut bag=before.inventory.clone();bag.restore_slot(0,Some(Item{id:output,count:1,vars:0})).unwrap();assert_eq!(d.inventory,bag);assert!(d.equipment.get(to).is_none());}}n+=1;}}}assert_eq!(n,8);println!("PG_WORN synthetic base/current requirement controls={n}");}
